import {canonicalSha256} from '../core/canonical-json.mjs';import {createDefaultTokenAccountingRegistry} from './token-accounting.mjs';
export async function compileWorkUnitContexts({model='fallback',hardInputLimit,outputReserve=0,safetyReserve=0,shared={},workUnits=[],registry=createDefaultTokenAccountingRegistry()}={}){if(!Number.isInteger(hardInputLimit)||hardInputLimit<=0)throw new TypeError('hardInputLimit is required');const availableInputTokens=hardInputLimit-outputReserve-safetyReserve;if(availableInputTokens<=0)throw new Error('No input budget remains');const contexts=[];const omissions=[];let totalEstimatedTokens=0;for(const unit of [...workUnits].sort((a,b)=>a.unitId.localeCompare(b.unitId))){const artifacts=(shared.artifacts??[]).filter(x=>(x.unitIds??[]).includes(unit.unitId));for(const item of shared.artifacts??[])if(!artifacts.includes(item))omissions.push({unitId:unit.unitId,category:'artifact',id:item.id,reason:'not related to work unit'});const messages=[{role:'system',content:shared.system??''},{role:'user',content:shared.task??''},{role:'user',content:JSON.stringify({unitId:unit.unitId,files:unit.files??[],artifacts,skills:unit.skillSections??[],rules:unit.rules??[],memory:unit.memory??[]})}];const estimatedTokens=await registry.countMessages(model,messages);contexts.push({unitId:unit.unitId,messages,estimatedTokens,contextSha256:canonicalSha256(messages)});totalEstimatedTokens+=estimatedTokens;}if(totalEstimatedTokens>availableInputTokens)throw new Error(`Work-unit contexts exceed global input budget: ${totalEstimatedTokens}/${availableInputTokens}`);const payload={schemaVersion:2,model,hardInputLimit,outputReserve,safetyReserve,availableInputTokens,totalEstimatedTokens,contexts,omissions};return Object.freeze({...payload,contextReceiptSha256:canonicalSha256(payload)});}
